import{_ as e,c as o,o as t,ah as r}from"./chunks/framework.Ch_PcVtW.js";const E=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"ja-jp/Management2/PART2/11.md","filePath":"ja-jp/Management2/PART2/11.md"}'),A={name:"ja-jp/Management2/PART2/11.md"};function n(l,a,i,p,B,S){return t(),o("div",null,[...a[0]||(a[0]=[r('<p>► 2023/05</p><h2 id="be-firstとmazzelのリリースを振り返る" tabindex="-1">BE:FIRSTとMAZZELのリリースを振り返る <a class="header-anchor" href="#be-firstとmazzelのリリースを振り返る" aria-label="Permalink to &quot;BE:FIRSTとMAZZELのリリースを振り返る&quot;">​</a></h2><p>#BEFIRST #MAZZEL #いい空気感</p><h3 id="「自身がわくわくし続けてくれると、おのずとわくわくした空気感が周囲に漂うし、人はそうした空気感に引きつけられると思う」" tabindex="-1">「自身がわくわくし続けてくれると、おのずとわくわくした空気感が周囲に漂うし、人はそうした空気感に引きつけられると思う」 <a class="header-anchor" href="#「自身がわくわくし続けてくれると、おのずとわくわくした空気感が周囲に漂うし、人はそうした空気感に引きつけられると思う」" aria-label="Permalink to &quot;「自身がわくわくし続けてくれると、おのずとわくわくした空気感が周囲に漂うし、人はそうした空気感に引きつけられると思う」&quot;">​</a></h3><p><strong>2023年春、BMSGの2つのボーイズグループが大きく動いた。1つは4月26日のBE:FIRSTの3rdシングル『Smile Again』のリリース、もう1つは5月17日、BE:FIRSTに次ぐ新たなグループMAZZEL(マーゼル)のデビューである。BE:FIRST『Smile Again』は、資生堂の「ANESSA Global Campaign Song」として大型タイアップもついた、自身初のラブソング。5月3日公開の Billboard JAPAN ダウンロード・ソング・チャート&quot;Download Songs&quot;で初登場1位を果たしたが、結果的にはBE:FIRSTが初めて Billboard JAPAN で総合ソング・チャート“JAPAN Hot 100”で1位を取れなかった曲となった。それを阻んだのはYOASOBIの『アイドル』。4月12日の配信開始以来、5月20日現在、Billboard JAPAN で総合ソング・チャート“JAPAN Hot 100&quot;で5週連続トップを独走し、Billboard JAPAN史上最速での1億回再生記録を打ち立てたモンスターヒット曲だ。</strong></p><p>BE:FIRSTはデビュー以来、『Gifted.』『Bye-Good-Bye』『Scream』『Boom Boom Back』と、1年半の間に計4曲で“JAPAN Hot 100”の1位を取ってきましたし、今回ももちろん取りたい気持ちはありました。でも、『アイドル』がすごすぎましたね。2023年の&quot;JAPAN Hot 100”の年間チャートの総合ポイント数で見ると、1位と2位が『アイドル』で、3位が『Smile Again』です(取材時点)BE:FIRSTがヒット作である前作『Bye-Good-Bye』よりも高い数字を取ることができたことに、強く手応えを感じました。</p><h3 id="予想以上の成長曲線を見せているmazzel" tabindex="-1">予想以上の成長曲線を見せているMAZZEL <a class="header-anchor" href="#予想以上の成長曲線を見せているmazzel" aria-label="Permalink to &quot;予想以上の成長曲線を見せているMAZZEL&quot;">​</a></h3><p><strong>一方、5月17日にリリースしたMAZZELのデビューシングル『Vivid』は Billboard JAPAN 総合ソング・チャート“JAPAN Hot 100”で4位、CDとラジオで1位を獲得した。多数局での月間パワープレイ枠に加え、リリース後はさらにリクエストオンエアを伸ばし、MVのコメント欄にはラジオをきっかけにアクセスした人も散見される。地上波でも放送されたオーディション「THE FIRST」が大きな話題になり、その勢いのままデビューしたBE:FIRSTに比べると派手さはないが、着実に音源から認知度を獲得していく兆しが見て取れる。過去のインタビューでも「BE:FIRSTとMAZZELは違うやり方を取る」ことはSKY-HI自身何度も繰り返し語っているが、今の出足はどう捉えているのか。</strong></p><p>一言で言うと、すごくいい感じと言えると思います。もちろん共同レーベル「BE-U」でタッグを組んだユニバーサルミュージックさんと一緒に進めていくなかで、数値や影響力での目標は設定していましたが、現時点でおおむね達成できている状況でよかったということもありますが、それよりは今のMAZZELメンバーが集まったときの空気感がとてもいい。具体的に想定できる成長幅や成長速度を考えても、今後に大きく期待できる状態だと思います。</p><p>改めて感じたのが、やっぱり「仲が良いグループは伸びる」んですよね。MAZZELの音楽番組でのパフォーマンスを見ていても、毎回どんどん良くなっています。世の中、残念ながら練習すればするだけ伸びるわけではありません。今のMAZZELは当然デビュー前ほどはたっぷりと練習時間が取れているわけではないですが、「映る」「見られる」という立場に変わった意識が芽生えたことを含めても、かなり早いタイミングで結構な成長スピードを見せてくれていることに驚いていますし、それが今の彼らの1番いいことかなと思います。</p><p>あとは彼ら自身がわくわくし続けてくれると、おのずとわくわくした空気感が周囲に漂ってくるグループになります。人はそうした空気感に引きつけられると思うので、そこはこれからも彼ら自身が育てていくべきポイントだと考えています。少なくとも今もその空気感があることは、非常に良いことと捉えています。</p><p>BMSGを立ち上げて最初の大型プロジェクトから生まれたBE：FIRSTのデビュー時とは、会社の状況が違うので、デビュー時に求める数値的目標なりも違ったものになっているのは事実です。BE:FIRSTのときは、本当にもう毎日毎日が倒産を賭けた勝負でしたから。それはおそらく他の事務所さんでも同じだと思います。先にグループがいれば、おのずと2つ目のグループでできることは増えてくる。MAZZELの場合はBE:FIRSTの存在があるからこそ、彼らで挑戦できる幅も広がってくると思っています。</p>',12)])])}const s=e(A,[["render",n]]);export{E as __pageData,s as default};
